import * as THREE from 'three';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import {MAP,insidePolygon,pathSamples} from './geography.js';
import {DISTRICT} from './district-data.js';

// One small authored botanical atlas, four instanced draw groups, no new model downloads.
export function createGroundGarden(scene,world,treeSites=[]){
 const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const c=canvas.getContext('2d'),texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=4;
 const footprints=[...MAP.buildings,...DISTRICT.buildings].filter(b=>b.p).map(b=>({p:b.p,minX:Math.min(...b.p.map(v=>v[0])),maxX:Math.max(...b.p.map(v=>v[0])),minZ:Math.min(...b.p.map(v=>v[1])),maxZ:Math.max(...b.p.map(v=>v[1]))}));
 const names=['grass','fern','shrub','flower'],sites=[],grid=new Map(),dummy=new THREE.Object3D(),frustum=new THREE.Frustum(),clip=new THREE.Matrix4(),sphere=new THREE.Sphere();let seed=73149,last=-Infinity,season='spring';
 const rnd=()=>((seed=Math.imul(seed,1664525)+1013904223>>>0)/4294967296);
 function leaf(x,y,angle,length,width,color){c.save();c.translate(x,y);c.rotate(angle);const g=c.createLinearGradient(-width,0,width,-length);g.addColorStop(0,'#304b2a');g.addColorStop(.48,color);g.addColorStop(1,'#829b54');c.fillStyle=g;c.beginPath();c.moveTo(0,0);c.bezierCurveTo(-width,-length*.25,-width*.8,-length*.8,0,-length);c.bezierCurveTo(width*.8,-length*.8,width,-length*.25,0,0);c.fill();c.strokeStyle='#c4c89277';c.lineWidth=.8;c.beginPath();c.moveTo(0,-2);c.lineTo(0,-length*.91);c.stroke();c.restore();}
 function paint(value){c.clearRect(0,0,512,512);for(let kind=0;kind<4;kind++){c.save();c.translate(kind%2*256,Math.floor(kind/2)*256);
 if(kind===0){for(let i=0;i<30;i++){const x=83+i*3.1,a=(i%7-3)*.12,h=48+(i*29%121);c.strokeStyle=['#4a6e35','#668447','#8e9e62'][i%3];c.lineWidth=1.7+i%2;c.beginPath();c.moveTo(x,248);c.quadraticCurveTo(x+Math.sin(a)*h*.6,205-h*.45,x+Math.sin(a)*h,247-h);c.stroke();}}
 if(kind===1){for(let j=0;j<7;j++){const a=(j-3)*.31,L=137+((j*17)%54);c.save();c.translate(128,247);c.rotate(a);c.strokeStyle='#637b40';c.lineWidth=2;c.beginPath();c.moveTo(0,0);c.quadraticCurveTo(6,-L*.5,0,-L);c.stroke();for(let i=1;i<=13;i++){const t=i/14,y=-L*t,len=(1-t)*36+5;for(const s of [-1,1])leaf(0,y,s*.9,len,4.5,'#688a48');}c.restore();}}
 if(kind===2){for(let j=0;j<6;j++){const x=60+j*25,y=210-(j%3)*28;c.strokeStyle='#665e3c';c.lineWidth=3;c.beginPath();c.moveTo(128,252);c.lineTo(x,y-60);c.stroke();for(let i=0;i<5;i++)leaf(x+(i%2?13:-10),y-i*20,(i%2?.7:-.7),40,14,'#567343');}}
 if(kind===3){const flowerColors={spring:['#ecc3d0','#fff0f2'],summer:['#b7c5eb','#e8e3fa'],autumn:['#e7d4a4','#fff0ce'],winter:['#e8e5db','#faf7ed']};for(let j=0;j<6;j++){const x=54+j*29,y=85+(j%3)*21;c.strokeStyle='#64824b';c.lineWidth=2.4;c.beginPath();c.moveTo(x+(j-2)*5,250);c.quadraticCurveTo(x-15,180,x,y);c.stroke();leaf(x,185,-.8,37,9,'#739352');leaf(x,160,.8,31,8,'#6d8b48');for(let k=0;k<5;k++){const a=k*Math.PI*.4;c.fillStyle=flowerColors[value][j%2];c.beginPath();c.ellipse(x+Math.cos(a)*9,y+Math.sin(a)*9,9,6,a,0,Math.PI*2);c.fill();}c.fillStyle='#c6a456';c.beginPath();c.arc(x,y,3,0,7);c.fill();}}
 c.restore();}texture.needsUpdate=true;}
 paint(season);
 const material=new THREE.MeshStandardMaterial({map:texture,alphaTest:.46,side:THREE.DoubleSide,roughness:.96,envMapIntensity:.4});material.name='參道草木・共用植物圖集';
 function geometry(kind){const planes=[];for(let i=0;i<(kind===1||kind===3?2:3);i++){const g=new THREE.PlaneGeometry(1,1);g.translate(0,.5,0);g.rotateY(i*Math.PI/(kind===1||kind===3?2:3)+.08);const uv=g.attributes.uv;for(let j=0;j<uv.count;j++)uv.setXY(j,kind%2*.5+uv.getX(j)*.5,(1-Math.floor(kind/2))*.5+uv.getY(j)*.5);planes.push(g);}const result=mergeGeometries(planes);planes.forEach(p=>p.dispose());return result;}
 function valid(x,z){if(x< -450||x>1240||z< -405||z>175)return false;const key=Math.floor(x)+','+Math.floor(z);for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++)if((grid.get((Math.floor(x)+a)+','+(Math.floor(z)+b))||[]).some(p=>Math.hypot(p.x-x,p.z-z)<1.05))return false;
 const near=world.surface.nearPath(x,z);if(near.distance<(near.s?.width||2.2)/2+.7||Number.isFinite(world.paving.height(x,z)))return false;
 if(footprints.some(b=>x>=b.minX&&x<=b.maxX&&z>=b.minZ&&z<=b.maxZ&&insidePolygon(x,z,b.p)))return false;if(MAP.water.some(w=>insidePolygon(x,z,w.p)))return false;
 const y=world.walkHeight(x,z);if(!Number.isFinite(y)||world.physics.collides(x,y,z))return false;for(const [dx,dz]of [[.3,0],[-.3,0],[0,.3],[0,-.3]]){const h=world.walkHeight(x+dx,z+dz);if(!Number.isFinite(h)||Math.abs(h-y)>.5)return false;}return{y,key};}
 const zones={station:0,precinct:0,mountain:0},limits={station:400,precinct:750,mountain:350};
 function plant(x,z,kind){const zone=x< -115?'station':x<320?'precinct':'mountain';if(sites.length>=1500||zones[zone]>=limits[zone])return;const ground=valid(x,z);if(!ground)return;const scale=(kind===0?.22:kind===1?.55:kind===2?.68:.36)*(1+rnd()*.5),p={x,y:ground.y+.018,z,kind,scale};if(x< -150){p.potScale=kind===2?.9:kind===0?.5:.7;dummy.position.set(x,p.y,z);dummy.rotation.set(0,0,0);dummy.scale.setScalar(p.potScale);dummy.updateMatrix();p.potMatrix=dummy.matrix.clone();p.y+=.34*p.potScale;}dummy.position.set(x,p.y,z);dummy.rotation.set(0,rnd()*Math.PI*2,0);dummy.scale.set(scale*(kind===2?1.2:1),scale,scale);dummy.updateMatrix();p.matrix=dummy.matrix.clone();p.color=new THREE.Color().setHSL(.0,.0,.82+rnd()*.17);sites.push(p);zones[zone]++;if(!grid.has(ground.key))grid.set(ground.key,[]);grid.get(ground.key).push(p);}
 // Denser planted beds beside the main approach, with all corridor/footprint checks retained.
 for(let x=-117;x< -30;x+=2.3)for(const side of [-1,1])for(const [i,band]of [6.1,7.8,10.4].entries())plant(x,side*band-1,i===0?3:i===1?2:1);
 for(const route of DISTRICT.routes)for(const p of pathSamples(route.p,3.5))for(const side of [-1,1]){const d=(route.width||4)/2+1.4;plant(p.x-p.dz*d*side,p.z+p.dx*d*side,sites.length%3===0?3:2);}
 const routes=[...MAP.routes,...MAP.paths.filter(p=>p.p.some(v=>v[0]<350&&v[0]>-450))];
 for(const route of routes){for(const p of pathSamples(route.p,7.5)){for(const side of [-1,1]){const d=(route.width||2.4)/2+1.15+rnd()*.9,x=p.x-p.dz*d*side,z=p.z+p.dx*d*side;plant(x,z,Math.floor(rnd()*4));plant(x+p.dx*.7-p.dz*.7*side,z+p.dz*.7+p.dx*.7*side,0);}if(sites.length>=1460)break;}if(sites.length>=1460)break;}
 for(const tree of treeSites.slice(0,80))for(const side of [-1,1])plant(tree.x+side*.95,tree.z+.9,sites.length%2?1:2);
 const groups=names.map((name,kind)=>{const points=sites.filter(p=>p.kind===kind),mesh=new THREE.InstancedMesh(geometry(kind),material,Math.max(1,points.length));mesh.name='參道植栽・'+name;mesh.frustumCulled=false;mesh.castShadow=false;mesh.receiveShadow=true;mesh.count=0;scene.add(mesh);return{mesh,points};});
 const potGeometry=new THREE.LatheGeometry([[.22,0],[.25,.035],[.31,.29],[.33,.29],[.33,.34],[.295,.35],[.275,.3],[.245,.03]].map(v=>new THREE.Vector2(...v)),12),potMaterial=new THREE.MeshStandardMaterial({color:'#8c6b56',roughness:.92}),pots=new THREE.InstancedMesh(potGeometry,potMaterial,sites.length);pots.name='町屋門前・素燒植木鉢';pots.frustumCulled=false;scene.add(pots);const soilGeometry=new THREE.CircleGeometry(.275,12);soilGeometry.rotateX(-Math.PI/2);soilGeometry.translate(0,.3,0);const soil=new THREE.InstancedMesh(soilGeometry,world.M.forest,sites.length);soil.name='植木鉢・土';soil.frustumCulled=false;scene.add(soil);pots.count=soil.count=0;
 const stats={gardenPots:sites.filter(p=>p.potMatrix).length,gardenClumps:sites.length,gardenZones:zones,gardenKinds:names.length,gardenVisible:0,gardenDrawGroups:groups.length+2,gardenAtlasKiB:canvas.width*canvas.height*4*4/3/1024};
 function update(camera){const now=performance.now();if(now-last<450)return;last=now;camera.updateMatrixWorld();frustum.setFromProjectionMatrix(clip.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse));let total=0,potCount=0;for(const {mesh,points}of groups){let count=0;for(const p of points){if(p.reserved)continue;const dx=p.x-camera.position.x,dy=p.y-camera.position.y,dz=p.z-camera.position.z,d=dx*dx+dy*dy+dz*dz,range=world.builder.integrated?58:85;if(d>range*range||season==='winter'&&p.kind===0)continue;sphere.center.set(p.x,p.y+p.scale*.5,p.z);sphere.radius=p.scale;if(!frustum.intersectsSphere(sphere))continue;if(p.potMatrix){pots.setMatrixAt(potCount,p.potMatrix);soil.setMatrixAt(potCount,p.potMatrix);potCount++;}mesh.setMatrixAt(count,p.matrix);mesh.setColorAt(count,p.color);count++;}mesh.count=count;mesh.visible=count>0;mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;total+=count;}pots.count=soil.count=potCount;pots.visible=soil.visible=potCount>0;pots.instanceMatrix.needsUpdate=soil.instanceMatrix.needsUpdate=true;stats.gardenVisible=total;}
 return{sites,groups,stats,update,setSeason(value){season=value;paint(value);last=-Infinity;}};
}
